using System;
using System.Windows;
using SftpSync.Core;
using SftpSync.Services;

namespace SftpSync.UI
{
    public partial class MainWindow : Window
    {
        private readonly ConfigService _configService;
        private readonly SftpService _sftpService;
        private readonly SyncEngine _syncEngine;
        private readonly EncryptionService _encryptionService;

        public MainWindow()
        {
            InitializeComponent();

            // On initialise nos composants
            _configService = new ConfigService();
            _sftpService = new SftpService();
            _syncEngine = new SyncEngine();
            _encryptionService = new EncryptionService();

            // Pré-configuration de test pour valider que tout fonctionne au premier clic
            PreconfigureDemoIfNeeded();
        }

        private void PreconfigureDemoIfNeeded()
        {
            var connections = _configService.GetConnections();
            var rules = _configService.GetRules();

            // Si c'est le tout premier démarrage, on crée une fausse connexion et une règle exemple
            if (connections.Count == 0)
            {
                var demoConn = new SftpConnection
                {
                    Name = "Serveur FTP Exemple",
                    Host = "127.0.0.1",
                    Port = 22,
                    Username = "andre",
                    EncryptedPassword = _encryptionService.Encrypt("MonMotDePasseSecret123")
                };
                connections.Add(demoConn);

                var demoRule = new SyncRule
                {
                    Name = "Envoi Factures XML",
                    LocalFolder = @"C:\SftpSource", // Dossier qu'on va surveiller
                    RemoteFolder = "/imports/factures",
                    ConnectionId = demoConn.Id,
                    FileFilter = "*.xml",
                    IsEnabled = true,
                    ArchiveAfterSend = true,
                    ArchiveFolder = @"C:\SftpArchive" // Dossier d'archivage après succès
                };
                rules.Add(demoRule);

                _configService.Save();
                
                TxtStatus.AppendText($"[INFO] Configuration démo créée automatiquement.\r\n");
                TxtStatus.AppendText($"[INFO] Pour tester la surveillance, crée le dossier local : C:\\SftpSource\r\n\r\n");
            }
        }

        private async void BtnTest_Click(object sender, RoutedEventArgs e)
        {
            var firstConn = _configService.GetConnections()[0];
            TxtStatus.AppendText($"[SFTP] Tentative de connexion à {firstConn.Host}:{firstConn.Port}...\r\n");

            // On lance le test via notre service SFTP
            var result = await _sftpService.TestConnectionAsync(firstConn);

            if (result.success)
            {
                TxtStatus.AppendText($"[SUCCÈS] Connexion réussie ! Empreinte du serveur : {result.fingerprint}\r\n");
            }
            else
            {
                // C'est normal que ça affiche une erreur si aucun serveur SFTP ne tourne sur 127.0.0.1 !
                TxtStatus.AppendText($"[ÉCHEC] Erreur attendue (Serveur démo éteint) : {result.errorMessage}\r\n");
            }
        }

        private void BtnStart_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                _syncEngine.Start();
                TxtStatus.AppendText("[MOTEUR] Surveillance démarrée en arrière-plan sur C:\\SftpSource (Filtre: *.xml)\r\n");
                BtnStart.IsEnabled = false; // On grise le bouton pour éviter de le relancer
            }
            catch (Exception ex)
            {
                TxtStatus.AppendText($"[ERREUR] Impossible de lancer le moteur : {ex.Message}\r\n");
            }
        }
    }
}
